<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class MatchSquad extends Model { protected $fillable=['organization_id','match_id','team_id','squad_id','status','created_by']; public function match():BelongsTo{return $this->belongsTo(CricketMatch::class,'match_id');} public function team():BelongsTo{return $this->belongsTo(Team::class);} public function squad():BelongsTo{return $this->belongsTo(Squad::class);} public function players():HasMany{return $this->hasMany(MatchSquadPlayer::class);} public function playingXi():HasMany{return $this->hasMany(PlayingXi::class);} public function battingOrder():HasMany{return $this->hasMany(BattingOrder::class);} public function bowlingAssignments():HasMany{return $this->hasMany(BowlingAssignment::class);} }